datasource db {
  provider = "sqlite"
  url      = env("DATABASE_URL")
}

generator client {
  provider = "prisma-client-js"
}

model Account {
  id       Int           @id @default(autoincrement())
  name     String        @unique
  balance  Int           @default(0)
  sent     LedgerEntry[] @relation("sentTransfers")
  received LedgerEntry[] @relation("receivedTransfers")
}

model LedgerEntry {
  id            Int      @id @default(autoincrement())
  amount        Int
  createdAt     DateTime @default(now())
  fromAccount   Account  @relation("sentTransfers", fields: [fromAccountId], references: [id])
  fromAccountId Int
  toAccount     Account  @relation("receivedTransfers", fields: [toAccountId], references: [id])
  toAccountId   Int
}

app bankapp {
  wasp: {
    version: "^0.16.0"
  },
  title: "bankapp",
  db: {
    seeds: [
      import { devSeed } from "@src/dbSeeds"
    ]
  }
}

route RootRoute { path: "/", to: MainPage }
page MainPage {
  component: import { MainPage } from "@src/MainPage"
}

export const devSeed = async (prisma: any) => {
  await prisma.ledgerEntry.deleteMany({})
  const accounts: Array<[string, number]> = [
    ["Alice", 100],
    ["Bob", 50],
  ]
  for (const [name, balance] of accounts) {
    await prisma.account.upsert({
      where: { name },
      update: { balance },
      create: { name, balance },
    })
  }
}

export const MainPage = () => {
  return (
    <div>
      <h1>bankapp</h1>
      <p>A minimal bank account ledger.</p>
    </div>
  )
}

export class HttpError extends Error {
  public statusCode: number
  public data: unknown

  constructor(
    statusCode: number,
    message?: string,
    data?: Record<string, unknown>,
    options?: ErrorOptions
  ) {
    super(message, options)

    if (Error.captureStackTrace) {
      Error.captureStackTrace(this, HttpError)
    }

    this.name = this.constructor.name

    if (
      !(Number.isInteger(statusCode) && statusCode >= 400 && statusCode < 600)
    ) {
      throw new Error('statusCode has to be integer in range [400, 600).')
    }
    this.statusCode = statusCode

    if (data) {
      this.data = data
    }
  }
}

